CREATE INDEX tasks_state_idx ON tasks(state, created_at);
CREATE UNIQUE INDEX attempts_effective_unique ON attempts(task_id)
    WHERE execution_state IN ('starting','executing','finalizing','uncertain');
CREATE INDEX attempts_active_idx ON attempts(execution_state);
CREATE INDEX attempts_model_service_idx
    ON attempts(model_harness, model_provider, model_model) WHERE model_model IS NOT NULL;
CREATE INDEX artifacts_task_idx ON artifacts(task_id);
CREATE INDEX events_task_idx ON events(task_id, seq);
CREATE INDEX events_decision_status_idx ON events(kind, seq DESC)
    WHERE kind IN ('decision.completed','decision.failed','decision.needs_host','decision.cancelled');
CREATE INDEX events_router_claimed_idx
    ON events(json_extract(CASE WHEN json_valid(payload_json) THEN payload_json END, '$.buddyId'), seq)
    WHERE kind='router.claimed';
CREATE INDEX resource_claims_state_idx ON resource_claims(state, kind);
CREATE INDEX attempt_activity_task_idx ON attempt_activity(task_id, updated_at);
CREATE INDEX messages_task_idx ON messages(task_id, created_at);
CREATE INDEX messages_state_idx ON messages(state);
CREATE INDEX buddies_current_idx ON buddies(available, buddy_id);
CREATE INDEX buddies_harness_idx ON buddies(harness, buddy_id);
CREATE INDEX evaluation_preferences_mode_idx ON evaluation_preferences(mode, buddy_id);
CREATE INDEX decision_requests_task_idx ON decision_requests(task_id);
CREATE INDEX evaluation_decisions_created_idx
    ON evaluation_decisions(created_at, decision_id);
CREATE INDEX macro_tasks_activity_idx ON macro_tasks(activity_seq DESC, macro_task_id DESC);
